// Screenshot compositor: all displayed UI pixels come from the supplied ZIP.
// Only viewport clipping, translation and blending are applied. No text, balances,
// buttons, card details or receipts are generated by this renderer.
export function createScreens(canvas) {
  const ctx=canvas.getContext('2d',{alpha:false});
  const image=id=>document.querySelector(`#source-${id}`);
  const state={page:'cards',scroll:0,previous:'cards',previousScroll:0,transition:1,style:'slide',stats:0};
  function stitch(first,second,delta){
    const c=document.createElement('canvas');c.width=720;c.height=1180+delta;
    const g=c.getContext('2d');g.drawImage(image(first),0,205,720,600,0,0,720,600);
    const start=805-delta;
    g.drawImage(image(second),0,start,720,1385-start,0,600,720,1385-start);return c;
  }
  const holders=stitch('03','04',247),requesters=stitch('05','06',517);
  const buffer=document.createElement('canvas');buffer.width=720;buffer.height=1100;
  const b=buffer.getContext('2d',{alpha:false});
  function page(name,scroll){
    b.fillStyle='#080d10';b.fillRect(0,0,720,1100);
    if(name==='cards'||name==='circle'){
      const id=name==='cards'?'04':'06',body=name==='cards'?holders:requesters;
      b.drawImage(body,0,Math.min(scroll,body.height-850),720,850,0,125,720,850);
      b.drawImage(image(id),0,80,720,125,0,0,720,125);
      b.drawImage(image(id),0,1385,720,125,0,975,720,125);
    }else{
      const id={menu:'10',history:'13',order:'16',chat:'15'}[name];
      if(name==='menu'){
        page('circle',790);
        b.fillStyle='#0008';b.fillRect(0,0,720,1100);
        b.drawImage(image(id),0,80,580,1100,0,0,580,1100);
      }
      else {
        const footer=name==='chat'?115:0,visible=975-footer;
        b.drawImage(image(id),0,205+Math.min(scroll,name==='chat'?430:330),720,visible,0,125,720,visible);
        b.drawImage(image(id),0,80,720,125,0,0,720,125);
        if(footer)b.drawImage(image(id),0,1395,720,115,0,985,720,115);
      }
    }
    return buffer;
  }
  function render(){
    ctx.fillStyle='#080d10';ctx.fillRect(0,0,720,1100);
    const p=state.transition;
    if(p<1){
      ctx.drawImage(page(state.previous,state.previousScroll),state.style==='slide'?-p*110:0,0);
      ctx.globalAlpha=state.style==='fade'?p:1;
      ctx.drawImage(page(state.page,state.scroll),state.style==='slide'?(1-p)*720:0,0);
      ctx.globalAlpha=1;
    }else ctx.drawImage(page(state.page,state.scroll),0,0);
  }
  return{state,render};
}
